{"statements": [
 {
  "id": "1a",
  "type": "FACT",
  "force": null,
  "force_from": null,
  "text": "FACT pavement markings tell a driver when it is not [?safe] to pass",
  "sources": [
   {
    "id": "m20",
    "quote": "Pavement markings divide traffic lanes, show turning lanes, mark pedestrian crossings, indicate obstacles and tell you when it is not safe to pass."
   }
  ],
  "flags": [
   {
    "code": "J",
    "span": "safe",
    "note": "Subjective safety; no observable test."
   }
  ],
  "links": [],
  "note": "Only the part of the sentence about passing is in scope; the other functions of pavement markings give no statement."
 },
 {
  "id": "3.1.5a",
  "type": "RULE",
  "force": "ADVISORY",
  "force_from": "text (\"should not pass\")",
  "text": "a driver SHOULD NOT pass WHEN there is a solid line at the left of the driver's lane BECAUSE it is not [?safe] to pass",
  "sources": [
   {
    "id": "m21",
    "quote": "A solid line at the left of your lane means it is unsafe to pass. ('A' should not pass.)"
   },
   {
    "id": "m22",
    "quote": "vehicles travelling beside a solid yellow line"
   }
  ],
  "flags": [
   {
    "code": "J",
    "span": "safe",
    "note": "Subjective safety; no observable test."
   }
  ],
  "links": [],
  "note": "The parenthetical names vehicle A in Diagram 3-2; the rule applies to any driver with a solid line at the left of the lane."
 },
 {
  "id": "3.1.6a",
  "type": "RULE",
  "force": "LEGAL",
  "force_from": "text (\"may pass\")",
  "text": "a driver MAY pass WHEN there is a broken line at the left of the driver's lane AND the way is [?clear] AND there are [?enough] broken lines ahead to complete the pass [?safely]",
  "sources": [
   {
    "id": "m23",
    "quote": "A broken line at the left of your lane means you may pass if the way is clear. ('A' may pass if there are enough broken lines ahead to complete the pass safely.)"
   },
   {
    "id": "m24",
    "quote": "vehicles travelling beside broken yellow lines"
   }
  ],
  "flags": [
   {
    "code": "J",
    "span": "clear",
    "note": "No measure of how clear the way must be."
   },
   {
    "code": "J",
    "span": "enough",
    "note": "No number of broken lines stated."
   },
   {
    "code": "J",
    "span": "safely",
    "note": "Subjective safety; no observable test."
   }
  ],
  "links": [],
  "note": "The parenthetical names vehicle A in Diagram 3-3; its extra condition is joined into the permission with AND."
 }
]}
